head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vCurrPageNo = 0; // 현재 선택된 페이지번호
scwin.gAcptNo;
scwin.gIsurCd;
scwin.gDate;
scwin.gDepCd;
scwin.gEmpNo;
scwin.gLdMktTp;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;
    scwin.gLdMktTp = js_market;

    //  기간 from~ to  셋팅
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    // 불성실유형  셋팅
    const sbmOptions = {
        id : "sbm_dts_NfaithTp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_NfaithTp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > async function() {
    // 일자 체크
    if (edt_FromDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if (edt_ToDate.getValue().length < 8) {
        await $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) === false) {
        return;
    }
    fn_Search();
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    // return (obj.checked) ? "Y" : "N";
    if (obj.checked === true) {
        return obj.getValue();
    } else {
        return "0";
    }

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************

};X < !불성실지정--;
목록검색(유가증권);
사용자;
클릭-- > function() {
    scwin.vCurrPageNo = 0;
    let bndListStat = scwin.getChkValue(chb_ListStatCd);
    if (bndListStat === "0") {
        bndListStat = "2"; // 채권공시 해제법인

    }
    const url_list = "/UnfaithfulDesign.do?method=listUnfaithfulSecuMktBond&inputMessageId=NFAITHSECUMKTCONDBOND_IN" + "&outputMessageId=NFAITHSECUMKTLISTBOND_OUT";
    const url_cond = "&ISUR_CD=" + txb_isur_cd.getValue() + "&FROM_DATE=" + edt_FromDate.getValue() + "&TO_DATE=" + edt_ToDate.getValue() + "&BND_LIST_STAT=" + bndListStat + "&SCREN_ID=" + 'ULDSTF35800.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // 그리드의 데이타 조회
    dts_nfaith_list.DataID = encodeURI(url_list + url_cond);
    dts_nfaith_list.reset();

    /*
    txb_companyCnt.value = "총회사수 : " ;
    var url_list2 = "/UnfaithfulDesign.do?method=listUnfaithfulKosdaqCnt&inputMessageId=NFAITHKOSDAQCOND_IN"
    		+ "&outputMessageId=NFAITHKOSDAQLISTCNT_OUT" ;
    var url_cond2 =  "&ISUR_CD="+ getObjectValue(txb_isur_cd)
    		+ "&FROM_DATE=" + getObjectValue(edt_FromDate)
    		+ "&TO_DATE=" + getObjectValue(edt_ToDate)
    		+ "&BND_LIST_STAT=" + bndListStat;

    // 그리드의 데이타 조회
    bnc_Company_Cnt.DataID = encodeURI(url_list2 + url_cond2);
    bnc_Company_Cnt.reset();
     */

};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_nfaith_list.getCellData(Number(obj), "ACPT_NO");
    scwin.gIsurCd = dts_nfaith_list.getCellData(Number(obj), "ISUR_CD");
};

/**
 * @method
 * @name grd_nfaith_list_OnDblClick
 * @description grd_nfaith_list 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_nfaith_list_OnDblClick = async function(row, colid) {
    scwin.setContnId(row);
    if (colid === "COM_ABBRV") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid === "CONTN") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF35800.xml');
    } else if (colid === "BND_ISU_NM") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF35800.xml');
    } else if (colid === "RSN_OCCR_DD") {
        // 2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        await $c.stf.openDisclViewer(scwin.gAcptNo, "R", 'ULDSTF35800.xml');
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    $c.stf.doLogSave('ULDSTF35800.xml', SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_nfaith_list, {fileName: "불성실공시법인지정 목록", type: "8"});
};

/**
 * @method
 * @name dts_NfaithTp_OnLoadError
 * @description dts_NfaithTp 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_NfaithTp_OnLoadError = async function() {
    await $c.win.alert(dts_NfaithTp);
};

/**
 * @method
 * @name dts_nfaith_list_OnLoadError
 * @description dts_nfaith_list 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_nfaith_list_OnLoadError = async function() {
    await $c.win.alert(dts_nfaith_list);
};

/**
 * @method
 * @name img_FromCal_onclick
 * @description img_FromCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};

/**
 * @method
 * @name img_ToCal_onclick
 * @description img_ToCal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.setFromToDate(vTp, edt_FromDate, edt_ToDate);
};

/**
 * @method
 * @name dts_nfaith_list_OnLoadCompleted
 * @description dts_nfaith_list 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_nfaith_list_OnLoadCompleted = async function(rowcount) {
    if (dts_nfaith_list.errorMsg) {
        await $c.win.alert(dts_nfaith_list.errorMsg);
    } else {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    }
};

/**
 * @method
 * @name txb_isur_cd_onblur
 * @description txb_isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() === "") {
        txb_com_abbrv.setValue("");
    }
};

/**
 * @method
 * @name txb_isur_cd_onfocus
 * @description txb_isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw !== "" && foColum === "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

        else return false;
    } else return true;
};

/**
 * @method
 * @name txb_isur_cd_onkeyup
 * @description txb_isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() === "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode === 40) {
            // 아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name img_com_srch_onclick
 * @description img_com_srch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearchBond(txb_isur_cd, txb_com_abbrv);
};

/**
 * @method
 * @name gform_onload
 * @description 패널라운드 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    // 패널라운드 처리
    $c.cm.PanelToGroupBox(panel_1);
    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
    await scwin.setCode();
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    fn_CheckCond();
};
